"""Zip slip: an archive entry name used as a path, in every language, with the fixed form (canonical path checked
against the destination, basename, or the library's safe accessor) that must stay quiet."""
from pathlib import Path

import pytest

from aletheore.flow.discover import discover_repo

CASES = [
    ('j1', 'src/Unzip.java', 'import java.io.*;\nimport java.util.zip.*;\npublic class Unzip {\n    public void extract(InputStream in, File dest) throws IOException {\n        ZipInputStream zis = new ZipInputStream(in);\n        ZipEntry entry;\n        while ((entry = zis.getNextEntry()) != null) {\n            File out = new File(dest, entry.getName());\n            FileOutputStream fos = new FileOutputStream(out);\n            fos.close();\n        }\n    }\n}\n', True),
    ('j2', 'src/Unzip.java', 'import java.io.*;\nimport java.util.zip.*;\npublic class Unzip {\n    public void extract(InputStream in, File dest) throws IOException {\n        ZipInputStream zis = new ZipInputStream(in);\n        ZipEntry entry;\n        while ((entry = zis.getNextEntry()) != null) {\n            File out = new File(dest, entry.getName());\n            if (!out.getCanonicalPath().startsWith(dest.getCanonicalPath() + File.separator)) {\n                throw new IOException("bad entry");\n            }\n            FileOutputStream fos = new FileOutputStream(out);\n            fos.close();\n        }\n    }\n}\n', False),
    ('p1', 'unz.py', 'import os, zipfile\ndef extract(path, dest):\n    with zipfile.ZipFile(path) as zf:\n        for info in zf.infolist():\n            with open(os.path.join(dest, info.filename), "wb") as f:\n                f.write(zf.read(info))\n', True),
    ('p2', 'unz.py', 'import os, zipfile\ndef extract(path, dest):\n    with zipfile.ZipFile(path) as zf:\n        for name in zf.namelist():\n            target = os.path.realpath(os.path.join(dest, name))\n            if not target.startswith(os.path.realpath(dest) + os.sep):\n                raise ValueError("bad entry")\n            with open(target, "wb") as f:\n                f.write(zf.read(name))\n', False),
    ('p3', 'unz.py', 'import os, zipfile\ndef extract(path, dest):\n    with zipfile.ZipFile(path) as zf:\n        for name in zf.namelist():\n            with open(os.path.join(dest, os.path.basename(name)), "wb") as f:\n                f.write(zf.read(name))\n', False),
    ('p4', 'unz.py', 'import os, zipfile\ndef extract(path, dest):\n    with zipfile.ZipFile(path) as zf:\n        for name in zf.namelist():\n            target = os.path.join(dest, name)\n            if not target.startswith(dest):\n                raise ValueError("bad entry")\n            with open(target, "wb") as f:\n                f.write(zf.read(name))\n', True),
    ('p5', 'unz.py', 'import os, zipfile\ndef extract(path, dest):\n    with zipfile.ZipFile(path) as zf:\n        for name in zf.namelist():\n            target = os.path.realpath(os.path.join(dest, name))\n            if os.path.commonpath([dest, target]) != dest:\n                raise ValueError("bad entry")\n            with open(target, "wb") as f:\n                f.write(zf.read(name))\n', False),
    ('g1', 'unzip.go', 'package main\n\nimport (\n\t"archive/zip"\n\t"io"\n\t"os"\n\t"path/filepath"\n)\n\nfunc unzip(src, dest string) error {\n\tr, err := zip.OpenReader(src)\n\tif err != nil {\n\t\treturn err\n\t}\n\tdefer r.Close()\n\tfor _, f := range r.File {\n\t\tpath := filepath.Join(dest, f.Name)\n\t\tout, err := os.Create(path)\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\trc, _ := f.Open()\n\t\tio.Copy(out, rc)\n\t}\n\treturn nil\n}\n', True),
    ('g2', 'unzip.go', 'package main\n\nimport (\n\t"archive/zip"\n\t"io"\n\t"os"\n\t"path/filepath"\n)\n\nfunc unzip(src, dest string) error {\n\tr, err := zip.OpenReader(src)\n\tif err != nil {\n\t\treturn err\n\t}\n\tdefer r.Close()\n\tfor _, f := range r.File {\n\t\tpath := filepath.Join(dest, f.Name)\n\t\tif !strings.HasPrefix(path, filepath.Clean(dest)+string(os.PathSeparator)) {\n\t\t\treturn nil\n\t\t}\n\t\tout, err := os.Create(path)\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\trc, _ := f.Open()\n\t\tio.Copy(out, rc)\n\t}\n\treturn nil\n}\n', False),
    ('c1', 'Unzip.cs', 'using System.IO;\nusing System.IO.Compression;\npublic class Unzipper {\n    public void Extract(string zipPath, string dest) {\n        using (var archive = ZipFile.OpenRead(zipPath)) {\n            foreach (var entry in archive.Entries) {\n                var destPath = Path.Combine(dest, entry.FullName);\n                entry.ExtractToFile(destPath);\n            }\n        }\n    }\n}\n', True),
    ('c2', 'Unzip.cs', 'using System.IO;\nusing System.IO.Compression;\npublic class Unzipper {\n    public void Extract(string zipPath, string dest) {\n        using (var archive = ZipFile.OpenRead(zipPath)) {\n            foreach (var entry in archive.Entries) {\n                var destPath = Path.GetFullPath(Path.Combine(dest, entry.FullName));\n                if (!destPath.StartsWith(Path.GetFullPath(dest) + Path.DirectorySeparatorChar)) {\n                    throw new IOException("bad entry");\n                }\n                entry.ExtractToFile(destPath);\n            }\n        }\n    }\n}\n', False),
    ('k1', 'Unzip.kt', 'import java.io.File\nimport java.io.FileOutputStream\nimport java.io.InputStream\nimport java.util.zip.ZipInputStream\n\nclass Unzip {\n    fun extract(input: InputStream, dest: File) {\n        val zis = ZipInputStream(input)\n        var entry = zis.nextEntry\n        while (entry != null) {\n            val out = File(dest, entry.name)\n            FileOutputStream(out).use { zis.copyTo(it) }\n            entry = zis.nextEntry\n        }\n    }\n}\n', True),
    ('k2', 'Unzip.kt', 'import java.io.File\nimport java.io.FileOutputStream\nimport java.io.InputStream\nimport java.util.zip.ZipInputStream\n\nclass Unzip {\n    fun extract(input: InputStream, dest: File) {\n        val zis = ZipInputStream(input)\n        var entry = zis.nextEntry\n        while (entry != null) {\n            val out = File(dest, entry.name)\n            if (!out.canonicalPath.startsWith(dest.canonicalPath + File.separator)) throw SecurityException("bad")\n            FileOutputStream(out).use { zis.copyTo(it) }\n            entry = zis.nextEntry\n        }\n    }\n}\n', False),
    ('js1', 'unzip.js', 'const AdmZip = require("adm-zip");\nconst fs = require("fs");\nconst path = require("path");\nfunction extract(buf, dest) {\n  const zip = new AdmZip(buf);\n  zip.getEntries().forEach((entry) => {\n    fs.writeFileSync(path.join(dest, entry.entryName), entry.getData());\n  });\n}\nmodule.exports = { extract };\n', True),
    ('js2', 'unzip.js', 'const yauzl = require("yauzl");\nconst fs = require("fs");\nconst path = require("path");\nfunction extract(file, dest) {\n  yauzl.open(file, { lazyEntries: true }, (err, zipfile) => {\n    zipfile.on("entry", (entry) => {\n      const out = fs.createWriteStream(path.join(dest, entry.fileName));\n    });\n  });\n}\nmodule.exports = { extract };\n', True),
    ('js3', 'unzip.js', 'const AdmZip = require("adm-zip");\nconst fs = require("fs");\nconst path = require("path");\nfunction extract(buf, dest) {\n  const zip = new AdmZip(buf);\n  const root = path.resolve(dest);\n  zip.getEntries().forEach((entry) => {\n    const target = path.resolve(root, entry.entryName);\n    if (!target.startsWith(root + path.sep)) { throw new Error("bad entry"); }\n    fs.writeFileSync(target, entry.getData());\n  });\n}\nmodule.exports = { extract };\n', False),
    ('r1', 'unzipper.rb', 'require "zip"\nclass Unzipper\n  def extract(path, dest)\n    Zip::File.open(path) do |zip|\n      zip.each do |entry|\n        entry.extract(File.join(dest, entry.name))\n      end\n    end\n  end\nend\n', True),
    ('r2', 'unzipper.rb', 'require "zip"\nclass Unzipper\n  def extract(path, dest)\n    root = File.expand_path(dest)\n    Zip::File.open(path) do |zip|\n      zip.each do |entry|\n        target = File.expand_path(File.join(root, entry.name))\n        raise "bad entry" unless target.start_with?(root + File::SEPARATOR)\n        entry.extract(target)\n      end\n    end\n  end\nend\n', False),
    ('rs1', 'src/lib.rs', 'use std::fs::File;\nuse std::path::Path;\npub fn extract(file: File, dest: &str) -> zip::result::ZipResult<()> {\n    let mut archive = zip::ZipArchive::new(file)?;\n    for i in 0..archive.len() {\n        let entry = archive.by_index(i)?;\n        let outpath = Path::new(dest).join(entry.name());\n        let _out = File::create(&outpath)?;\n    }\n    Ok(())\n}\n', True),
    ('rs2', 'src/lib.rs', 'use std::fs::File;\nuse std::path::Path;\npub fn extract(file: File, dest: &str) -> zip::result::ZipResult<()> {\n    let mut archive = zip::ZipArchive::new(file)?;\n    for i in 0..archive.len() {\n        let entry = archive.by_index(i)?;\n        let outpath = Path::new(dest).join(entry.enclosed_name().unwrap());\n        let _out = File::create(&outpath)?;\n    }\n    Ok(())\n}\n', False),
    ('ph1', 'unzip.php', "<?php\nfunction extract_zip($path, $dest) {\n    $zip = new ZipArchive();\n    $zip->open($path);\n    for ($i = 0; $i < $zip->numFiles; $i++) {\n        $name = $zip->getNameIndex($i);\n        file_put_contents($dest . '/' . $name, $zip->getFromIndex($i));\n    }\n}\n", True),
]


@pytest.mark.parametrize("name,rel,src,vulnerable", CASES, ids=[c[0] for c in CASES])
def test_zip_slip(tmp_path: Path, name, rel, src, vulnerable):
    p = tmp_path / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(src)
    found = [f for f in discover_repo(tmp_path) if f["rule_id"].endswith("path-traversal")]
    assert bool(found) is vulnerable, found
